    params: {
      type: Object,
      required: true
    }
  },
  // props: {
  //   formSelected: Object,
  //   flowStepsData: Array,
  //   currentConfigSteps: Array,
  //   currentZeroStep: Array,
  // },
  created() {
    if (this.params.currentStartStep.length > 0) {
      this.formElements = this.params.currentStartStep;
    }
    if (this.params.currentConfigSteps.length > 0) {
      this.flowDesignerSteps = [];
      this.flowDesignerSteps = this.params.currentConfigSteps;
      // this.fetch_data(this.formInfo.form_template);
    } else {
      this.flowDesignerSteps = [];
      var data2 = JSON.parse(localStorage.getItem("flowStepsInfo"));
      this.flowDesignerSteps = data2;
      this.currentSelectedFlow = data2;
      var data = JSON.parse(localStorage.getItem("zeroStep"));
      this.formElements = data;
      this.zeroStepInfo = data;
    }
  },
  data() {
    return {
      flowDesignerSteps: [],
      stepHeaders: [{
        text: "Form Field",
        align: "start",
        sortable: false,
        value: "display_label"
      }, {
        text: "Visible",
        align: "start",
        sortable: false,
        value: "is_displayed"
      }, {
        text: "Editable",
        align: "start",
        sortable: false,
        value: "is_editable"
      }, {
        text: "Mandatory",
        align: "start",
        sortable: false,
        value: "is_required"
      }],
      headers: [{
        text: "Form Field",
        align: "start",
        sortable: false,
        value: "display_label"
      }, {
        text: "Visible",
        align: "start",
        sortable: false,
        value: "is_displayed"
      }, {
        text: "Editable",
        align: "start",
        sortable: false,
        value: "is_editable"
      }, {
        text: "Mandatory",
        align: "start",
        sortable: false,
        value: "is_required"
      }],
      componentCheck: 0,
      editformFields: false,
      fieldsData: [],
      formElements: [],
      stepName: "",
      stepIndex: 0,
      zeroStepInfo: [],
      currentSelectedFlow: []
    };
  },
  methods: {
    next_option() {
      var data = [];
      data = this.flowSteps;
      this.$emit("configuredSteps", this.flowDesignerSteps);
      this.$emit("zeroFlow", this.formElements);
    },
    back_option() {
      var data2 = [];
      data2 = this.params.flowStepsData;
      this.$emit("previousStep", data2);
    },
    edit_field_properties(Step, formfieldsArry, index) {
      this.fieldsData = [];
      this.componentCheck = 1;
      this.editformFields = true;
      this.fieldsData = formfieldsArry;
      this.stepName = Step;
      this.stepIndex = index;
    },
    save_updated_changes(value, name, index) {
      if (name == "Start") {
        this.formElements.forEach(element => {
          value.forEach(element2 => {
            if (element.display_label == element2.label) {
              element.is_displayed = element2.visible;
              element.is_editable = element2.editable;
              element.is_required = element2.mandatory;
            }
          });
        });
        // this.formElements = this.zeroStepInfo;
      } else if (name == this.stepName && index == this.stepIndex) {
        for (var j = 0; j < this.currentSelectedFlow[index].formDetails.length; j++) {
          for (var k = 0; k < value.length; k++) {
            if (this.currentSelectedFlow[index].formDetails[j].display_label == value[k].label) {
              this.currentSelectedFlow[index].formDetails[j].is_displayed = value[k].visible;
              this.currentSelectedFlow[index].formDetails[j].is_editable = value[k].editable;
              this.currentSelectedFlow[index].formDetails[j].is_required = value[k].mandatory;
            }
          }
        }
      }
      this.editformFields = false;
    }
  }
};
